// Dateien (ALLY 42, Weg B): gebaute Web-App aus dem Repo holen. Repo und Ordner aus den Einstellungen (webapp_repo, webapp_pfad), Stand = Zweig oder Commit
// (ref beim Aufruf), Standard main. Ohne Einstellung bricht der Lauf ab, nichts wird geändert.
const Q = $input.first().json || {};
const A = $('Aufruf').isExecuted ? ($('Aufruf').first().json || {}) : {};
const repo = String(Q.repo || '').trim(), pfad = String(Q.pfad || '').trim().replace(/^\/+|\/+$/g, '');
if (!/^[A-Za-z0-9_.-]{1,100}\/[A-Za-z0-9_.-]{1,100}$/.test(repo)) throw new Error('Web-App: Einstellung webapp_repo fehlt oder ist ungültig (Form inhaber/repo).');
if (!/^[A-Za-z0-9_.\/-]{1,200}$/.test(pfad) || pfad.includes('..')) throw new Error('Web-App: Einstellung webapp_pfad fehlt oder ist ungültig (z. B. webapp/dist).');
const ref = String(A.ref || 'main');
if (!/^[A-Za-z0-9._\/-]{1,80}$/.test(ref)) throw new Error('Web-App: ungültiger Stand ' + ref);
return ['app.js', 'app.css'].map(name => ({ json: { name, url: 'https://api.github.com/repos/' + repo + '/contents/' + pfad + '/' + name + '?ref=' + encodeURIComponent(ref), quelle: repo + '/' + pfad + '@' + ref } }));

// Dateien prüfen (ALLY 42): gebaute Web-App aus dem Repo (webapp/dist/app.js, app.css). Nur übernehmen, wenn beide da und plausibel sind; Fassung = FNV-Prüfsumme.
const Q = $('Dateien').all().map(x => x.json);
const R = $input.all().map(x => x.json);
const fnv = t => { let a = 2166136261, b = 5381; for (let i = 0; i < t.length; i++) { const c = t.charCodeAt(i); a ^= c; a = Math.imul(a, 16777619) >>> 0; b = (Math.imul(b, 33) + c) >>> 0; } return a.toString(16).padStart(8, '0') + b.toString(16).padStart(8, '0'); };
const aus = [];
Q.forEach((q, i) => {
  const t = String((R[i] || {}).data ?? '');
  const ok = q.name === 'app.js' ? t.length > 10000 && !/^\s*</.test(t) : t.length > 1000 && !/^\s*</.test(t);
  if (!ok) throw new Error('Web-App: ' + q.name + ' fehlt oder ist unplausibel (' + t.length + ' Zeichen). Nichts übernommen.');
  aus.push({ json: { name: q.name, inhalt: t, fassung: fnv(t), bytes: Buffer.byteLength(t, 'utf8'), quelle: q.quelle } });
});
return aus;
